import React from "react";
import WishlistButton from "@/components/wishlist/wishlist-button";

export default function HeaderSection({
  tourData,
  availabilityLoading,
  prices,
}: {
  tourData: any;
  availabilityLoading: any;
  prices: any;
}) {
  const reviewCount = tourData?.review_count || tourData?.reviews?.length || 0;
  const rating = tourData?.rating || 4.8;
  const tourImage =
    tourData?.media?.find((m: any) => m.main)?.main ??
    tourData?.media?.[0]?.high ??
    undefined;

  return (
    <div>
      <h1 className="tw-font-display tw-text-2xl tw-font-bold tw-text-[#14101c] tw-mt-0 tw-mb-2">
        {tourData.name}
      </h1>
      <div
        className="tw-my-1 tw-flex tw-flex-wrap tw-items-center tw-gap-2"
        style={{ fontSize: "14px", lineHeight: 1.2 }}
      >
        <WishlistButton
          variant="link"
          tour={{
            id: tourData.id,
            slug: tourData.slug,
            name: tourData.name,
            image: tourImage,
          }}
        />
        <span className="tw-text-[#5d556c]">·</span>
        {reviewCount > 0 && (
          <a
            href="#reviews"
            className="tw-inline-flex tw-items-center tw-gap-1 tw-no-underline"
            style={{ color: "inherit", whiteSpace: "nowrap" }}
          >
            <svg
              width="15"
              height="15"
              viewBox="0 0 24 24"
              fill="#f59e0b"
              aria-hidden="true"
              style={{ display: "block", marginTop: "-1px" }}
            >
              <path d="M12 17.27L18.18 21l-1.64-7.03L22 9.24l-7.19-.61L12 2 9.19 8.63 2 9.24l5.46 4.73L5.82 21z" />
            </svg>
            <span className="tw-text-[#14101c]" style={{ fontWeight: 500 }}>
              {rating.toFixed(1)}
            </span>
            <span className="tw-text-[#5d556c]">
              ({reviewCount} {reviewCount === 1 ? "review" : "reviews"})
            </span>
          </a>
        )}
        {reviewCount > 0 && <span className="tw-text-[#5d556c]">·</span>}
        <span style={{ whiteSpace: "nowrap" }}>
          {tourData.defaults?.duration?.days == 1
            ? "Daily"
            : tourData.defaults?.duration?.days + " Days"}
          ,{" "}
          {`${tourData.routes?.length} ${tourData.routes?.length == 1 ? "Destination" : "Destinations"
            }`}
        </span>
        {tourData.startLocation && (
          <>
            <span className="tw-text-[#5d556c]">·</span>
            <span style={{ whiteSpace: "nowrap" }}>
              Starts from <strong>{tourData.startLocation}</strong>
            </span>
          </>
        )}
      </div>
    </div>
  );
}
