import { apiv2Base, apiv2ServerHeaders } from "@/services/apiv2";
export default function getTourAvailabilityMonths({ tourId }: { tourId: number; }) {

    const res = fetch(
        `${apiv2Base()}/b2c/pricemonths/tour/${tourId}`, {
        method: "GET",
        headers: {
            ...apiv2ServerHeaders(),
            "Content-type": "application/json",
        },
        cache: "no-store"
    })
        .then((res) => res.json())
        // Ağ hatası / kullanıcı sayfadan ayrıldı: reject etmek yerine boş diziye düş.
        // Aksi halde unhandled rejection → "Failed to fetch" Sentry'e gürültü olur.
        // (Dizi normalize etme; caller zaten .length/.filter ile any üzerinde çalışıyor.)
        .catch(() => []);

    return res;
}
