const Check = () => (
  <span className="tw-shrink-0 tw-flex tw-h-7 tw-w-7 tw-items-center tw-justify-center tw-rounded-full tw-bg-[#854ec9] tw-text-white">
    <svg
      width="14"
      height="14"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={3}
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <path d="M5 13l4 4L19 7" />
    </svg>
  </span>
);

const Star = ({ size = 14, fill = "#fff" }: { size?: number; fill?: string }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill={fill}>
    <path d="M12 17.27 18.18 21l-1.64-7.03L22 9.24l-7.19-.61L12 2 9.19 8.63 2 9.24l5.46 4.73L5.82 21z" />
  </svg>
);

const TrustpilotBadge = () => (
  <a
    href="https://www.trustpilot.com/review/travelshopbooking.com"
    target="_blank"
    className="tw-inline-flex tw-flex-col tw-gap-2 tw-no-underline"
  >
    <div className="tw-flex tw-items-center tw-gap-2.5">
      <span className="tw-inline-flex tw-items-center tw-gap-1">
        <Star size={18} fill="#00b67a" />
        <span className="tw-text-[16px] tw-font-bold tw-tracking-tight tw-text-[#14101c]">
          Trustpilot
        </span>
      </span>
      <span className="tw-flex tw-gap-[2px]">
        {[0, 1, 2, 3, 4].map((i) => (
          <span
            key={i}
            className="tw-flex tw-h-[22px] tw-w-[22px] tw-items-center tw-justify-center tw-bg-[#00b67a]"
          >
            <Star size={14} />
          </span>
        ))}
      </span>
    </div>
    <span className="tw-text-[13px] tw-text-[#5d556c]">
      Based on <b className="tw-text-[#14101c]">100</b> reviews on Trustpilot
    </span>
  </a>
);

export default function WhyBook() {
  const benefits = [
    "Best price quaranteed.",
    "No credit card or booking fees.",
    "100% financial protection.",
    "Carbon neutral tours.",
    "Earn $20+ in travel credits.",
  ];

  return (
    <div className="tw-my-6 tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-p-6 md:tw-p-8">
      <h3 className="tw-font-display tw-m-0 tw-text-[22px] tw-font-bold tw-tracking-tight tw-text-[#14101c]">
        Why book with TravelShop Booking
      </h3>
      <div className="tw-mt-6 tw-grid sm:tw-grid-cols-2 tw-gap-x-8 tw-gap-y-4">
        {benefits.map((text) => (
          <div
            key={text}
            className="tw-flex tw-items-center tw-gap-3 tw-text-[15px] tw-text-[#2a2336]"
          >
            <Check />
            {text}
          </div>
        ))}
      </div>
      <div className="tw-mt-6 tw-pt-5 tw-border-0 tw-border-t tw-border-solid tw-border-[#ece9f1]">
        <TrustpilotBadge />
      </div>
    </div>
  );
}
