"use client";
import { useEffect, useState, useRef } from "react";
import Departures from "./departures";
import Inquiry from "./inquiry";
import { inputCls, spinnerCls } from "../ui";
import { parsePlainDate } from "@/helpers/plainDate";

const sectionTitle =
  "tw-font-display tw-text-[22px] tw-font-bold tw-tracking-tight tw-text-[#14101c]";
const subTitle = "tw-text-[18px] tw-font-semibold tw-text-[#14101c] tw-mb-4";

const toggleBase =
  "tw-inline-flex tw-items-center tw-gap-2 tw-px-4 tw-py-2 tw-rounded-full tw-border tw-border-solid tw-text-[14px] tw-font-semibold tw-cursor-pointer tw-transition-colors";
const toggleActive = `${toggleBase} tw-bg-[#854ec9] tw-text-white tw-border-[#854ec9]`;
const toggleIdle = `${toggleBase} tw-bg-white tw-text-[#854ec9] tw-border-[#854ec9] hover:tw-bg-[#faf9fc]`;

export default function Availability({
  slug,
  tourId,
  prices,
  accommodation,
  departureMonths,
  availabilityLoading,
  availabilityPriceLoading,
  availabilityFilters,
  availabilityFilterChange,
  groupSizeMin,
  groupSizeMax,
}: {
  slug: string;
  tourId: number;
  prices: any;
  accommodation: any;
  departureMonths: any;
  availabilityLoading: any;
  availabilityPriceLoading: any;
  availabilityFilters: any;
  availabilityFilterChange: any;
  groupSizeMin: number;
  groupSizeMax: number;
}) {
  const [showInquiry, setShowInquiry] = useState(false);
  const isInitialMount = useRef(true);

  useEffect(() => {
    if (
      isInitialMount.current &&
      availabilityFilters.serviceType === "" &&
      Object.keys(prices).length > 0
    ) {
      availabilityFilterChange({
        ...availabilityFilters,
        serviceType:
          prices.is_regular &&
          prices.regular_price > 0 &&
          availabilityFilters.serviceType === ""
            ? "regular"
            : "private",
      });
      isInitialMount.current = false;
    }
  }, [prices]);

  const travelerList = () => {
    const listItems = [];
    for (let i = groupSizeMin; i <= groupSizeMax; i++) {
      listItems.push(
        <option key={i} value={i}>
          {i}
        </option>
      );
    }
    return listItems;
  };

  const loadingBlock = (
    <div className="tw-text-center tw-my-6">
      <span className={`${spinnerCls} tw-text-[#854ec9] tw-h-8 tw-w-8`} role="status"></span>
      <p className="tw-mt-3">Loading. Please wait.</p>
    </div>
  );

  // Group departure months by year so we can render a year heading with its
  // months underneath.
  const monthsByYear: Record<string, string[]> = {};
  (departureMonths || []).forEach((m: string) => {
    const y = String(parsePlainDate(m).getFullYear());
    if (!monthsByYear[y]) monthsByYear[y] = [];
    monthsByYear[y].push(m);
  });

  const monthBtnCls = (month: string) =>
    `tw-w-full tw-inline-flex tw-items-center tw-justify-center tw-px-3 tw-py-2 tw-rounded-full tw-border tw-border-solid tw-text-[14px] tw-font-semibold tw-cursor-pointer tw-transition-colors disabled:tw-opacity-60 ${
      availabilityFilters.departureMonth === month
        ? "tw-bg-[#854ec9] tw-text-white tw-border-[#854ec9]"
        : "tw-bg-white tw-text-[#854ec9] tw-border-[#854ec9] hover:tw-bg-[#faf9fc]"
    }`;

  if (availabilityLoading)
    return (
      <div className="tw-mt-4" id="availability">
        <h2 className={sectionTitle}>Availability</h2>
        <div className="tw-mt-6">{loadingBlock}</div>
      </div>
    );

  if (!prices.is_regular && !prices.is_private)
    return (
      <div className="tw-mt-4" id="availability">
        <h2 className={sectionTitle}>Availability</h2>
        <div className="tw-mt-6">
          <Inquiry tourId={tourId} />
        </div>
      </div>
    );

  return (
    <div className="tw-mt-4" id="availability">
      <h2 className={sectionTitle}>Availability</h2>
      <div>
        <div>
          <div className="tw-mt-6">
            <p className={subTitle}>Service Type</p>
            {prices.is_regular && prices.regular_price > 0 && (
              <button
                type="button"
                className={`${
                  availabilityFilters.serviceType === "regular"
                    ? toggleActive
                    : toggleIdle
                } tw-mr-3`}
                onClick={() => {
                  setShowInquiry(false);
                  availabilityFilterChange({
                    ...availabilityFilters,
                    serviceType: "regular",
                  });
                }}
              >
                <svg
                  enableBackground="new 0 0 24 24"
                  version="1.0"
                  width="26"
                  height="26"
                  viewBox="0 0 24 24"
                  xmlSpace="preserve"
                  fill="currentColor"
                  xmlns="http://www.w3.org/2000/svg"
                  xmlnsXlink="http://www.w3.org/1999/xlink"
                >
                  <g>
                    <path d="M9,9c0-1.7,1.3-3,3-3s3,1.3,3,3c0,1.7-1.3,3-3,3S9,10.7,9,9z M12,14c-4.6,0-6,3.3-6,3.3V19h12v-1.7C18,17.3,16.6,14,12,14z   " />
                  </g>
                  <g>
                    <g>
                      <circle cx="18.5" cy="8.5" r="2.5" />
                    </g>
                    <g>
                      <path d="M18.5,13c-1.2,0-2.1,0.3-2.8,0.8c2.3,1.1,3.2,3,3.2,3.2l0,0.1H23v-1.3C23,15.7,21.9,13,18.5,13z" />
                    </g>
                  </g>
                  <g>
                    <g>
                      <circle cx="18.5" cy="8.5" r="2.5" />
                    </g>
                    <g>
                      <path d="M18.5,13c-1.2,0-2.1,0.3-2.8,0.8c2.3,1.1,3.2,3,3.2,3.2l0,0.1H23v-1.3C23,15.7,21.9,13,18.5,13z" />
                    </g>
                  </g>
                  <g>
                    <g>
                      <circle cx="5.5" cy="8.5" r="2.5" />
                    </g>
                    <g>
                      <path d="M5.5,13c1.2,0,2.1,0.3,2.8,0.8c-2.3,1.1-3.2,3-3.2,3.2l0,0.1H1v-1.3C1,15.7,2.1,13,5.5,13z" />
                    </g>
                  </g>
                </svg>{" "}
                Group Tour
              </button>
            )}
            <button
              type="button"
              className={
                availabilityFilters.serviceType === "private"
                  ? toggleActive
                  : toggleIdle
              }
              onClick={() => {
                availabilityFilterChange({
                  ...availabilityFilters,
                  serviceType: "private",
                });

                if (!prices.is_private) setShowInquiry(true);
              }}
            >
              <svg
                xmlns="http://www.w3.org/2000/svg"
                width="24"
                height="24"
                fill="currentColor"
                viewBox="0 0 18 18"
              >
                <path d="M12.5 16a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7m1.679-4.493-1.335 2.226a.75.75 0 0 1-1.174.144l-.774-.773a.5.5 0 0 1 .708-.708l.547.548 1.17-1.951a.5.5 0 1 1 .858.514ZM11 5a3 3 0 1 1-6 0 3 3 0 0 1 6 0M8 7a2 2 0 1 0 0-4 2 2 0 0 0 0 4" />
                <path d="M8.256 14a4.474 4.474 0 0 1-.229-1.004H3c.001-.246.154-.986.832-1.664C4.484 10.68 5.711 10 8 10c.26 0 .507.009.74.025.226-.341.496-.65.804-.918C9.077 9.038 8.564 9 8 9c-5 0-6 3-6 4s1 1 1 1z" />
              </svg>{" "}
              Private Tour
            </button>
          </div>
          {!showInquiry && (
            <div className="tw-mt-6">
              <p className={subTitle}>Traveler(s)</p>

              <select
                className={inputCls}
                id="availabilityFilterTravelers"
                aria-label="Select travelers"
                value={availabilityFilters.travelers}
                onChange={(e) => {
                  availabilityFilterChange({
                    ...availabilityFilters,
                    travelers: e.target.value,
                  });
                }}
                disabled={availabilityPriceLoading}
              >
                {travelerList()}
              </select>
            </div>
          )}
        </div>
        {!showInquiry && (
          <div className="tw-mt-6 tw-hidden md:tw-block">
            <p className="tw-text-[18px] tw-font-semibold tw-text-[#14101c]">
              Departure Month
            </p>
            {Object.keys(monthsByYear)
              .sort()
              .map((year) => (
                <div key={year} className="tw-mt-4">
                  <p className="tw-mb-2 tw-text-[13px] tw-font-bold tw-uppercase tw-tracking-[0.06em] tw-text-[#5d556c]">
                    {year}
                  </p>
                  <div className="tw-grid tw-grid-cols-4 tw-gap-3">
                    {monthsByYear[year].map((month: string) => {
                      const displayMonth = parsePlainDate(month);
                      return (
                        <button
                          key={"departure-date-" + month}
                          className={monthBtnCls(month)}
                          onClick={(e) => {
                            availabilityFilterChange({
                              ...availabilityFilters,
                              departureMonth: month,
                            });
                          }}
                          disabled={availabilityPriceLoading}
                        >
                          {availabilityPriceLoading &&
                            availabilityFilters.departureMonth === month && (
                              <>
                                <span className={`${spinnerCls} tw-mr-2`} aria-hidden="true"></span>{" "}
                              </>
                            )}
                          {displayMonth.toLocaleString("en-US", {
                            month: "long",
                          })}
                        </button>
                      );
                    })}
                  </div>
                </div>
              ))}
          </div>
        )}
        {!showInquiry && (
          <div className="tw-mt-6 md:tw-hidden">
            <div className="tw-mb-4">
              <label
                htmlFor="availabilityFilterDepartureMonth"
                className="tw-block tw-mb-2 tw-text-[18px] tw-font-semibold tw-text-[#14101c]"
              >
                Departure Month
              </label>
              <select
                className={inputCls}
                id="availabilityFilterDepartureMonth"
                aria-label="Select departure month"
                defaultValue={availabilityFilters.departureMonth}
                onChange={(e) => {
                  availabilityFilterChange({
                    ...availabilityFilters,
                    departureMonth: e.target.value,
                  });
                }}
                disabled={availabilityPriceLoading}
              >
                {departureMonths.map((month: string, index: number) => {
                  var displayMonth = parsePlainDate(month);
                  return (
                    <option value={month} key={"departure-date-" + month}>
                      {displayMonth.toLocaleString("en-US", {
                        month: "long",
                      })}{" "}
                      {displayMonth.getFullYear()}
                    </option>
                  );
                })}
              </select>
            </div>
          </div>
        )}

        {showInquiry ? (
          <Inquiry tourId={tourId} />
        ) : (
          <>
            {!availabilityPriceLoading ? (
              <Departures
                data={prices}
                slug={slug}
                accommodation={accommodation}
                serviceType={availabilityFilters.serviceType}
                travelers={availabilityFilters.travelers}
              />
            ) : (
              loadingBlock
            )}
          </>
        )}
      </div>
    </div>
  );
}
