"use client";
import React, { useEffect, useRef, useState, useMemo } from "react";
import styles from "./menu.module.css";

const ALL_ITEMS = [
  {
    label: "Overview",
    href: "#overview",
    visible: (t: any) => !!t?.description,
  },
  {
    label: "Attractions",
    href: "#attractions",
    visible: (t: any) => t?.attractions?.length > 0,
  },
  {
    label: "Highlights",
    href: "#highlights",
    visible: (t: any) => t?.highlights?.length > 0,
  },
  {
    label: "Itinerary",
    href: "#itinerary",
    visible: (t: any) => t?.itineraries?.length > 0,
  },
  {
    label: "Includes",
    href: "#includes",
    visible: (t: any) => t?.included?.length > 0 && t?.excluded?.length > 0,
  },
  {
    label: "Availability",
    href: "#availability",
    visible: () => true,
  },
  {
    label: "Reviews",
    href: "#reviews",
    visible: (t: any) => t?.reviews?.length > 0,
  },
];

const Menu = ({ tourData }: { tourData?: any }) => {
  const [activeSection, setActiveSection] = useState<string>("");
  const [isSticky, setIsSticky] = useState(false);
  const [indicatorStyle, setIndicatorStyle] = useState({ left: 0, width: 0 });
  const sentinelRef = useRef<HTMLDivElement>(null);
  const navRef = useRef<HTMLElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  const menuItems = useMemo(
    () => ALL_ITEMS.filter((item) => item.visible(tourData)),
    [tourData]
  );

  const sectionIds = useMemo(
    () => menuItems.map((item) => item.href.replace("#", "")),
    [menuItems]
  );

  useEffect(() => {
    const sentinel = sentinelRef.current;
    if (!sentinel) return;
    const observer = new IntersectionObserver(
      ([entry]) => setIsSticky(!entry.isIntersecting),
      { threshold: 0 }
    );
    observer.observe(sentinel);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (sectionIds.length === 0) return;
    const handleScroll = () => {
      const scrollY = window.scrollY + 100;
      let current = sectionIds[0];
      for (const id of sectionIds) {
        const el = document.getElementById(id);
        if (el && el.offsetTop <= scrollY) current = id;
      }
      setActiveSection(current);
    };
    window.addEventListener("scroll", handleScroll, { passive: true });
    handleScroll();
    return () => window.removeEventListener("scroll", handleScroll);
  }, [sectionIds]);

  useEffect(() => {
    if (!navRef.current || !activeSection) return;
    const activeEl = navRef.current.querySelector<HTMLElement>(
      `[data-section="${activeSection}"]`
    );
    if (activeEl) {
      // Aktif sekmeyi yatay şeritte ortala. Kayan asıl eleman dıştaki
      // konteyner (scrollRef); scrollIntoView dikey olarak sayfayı da
      // kaydırdığı için kullanmıyoruz.
      const container = scrollRef.current;
      if (container) {
        const cRect = container.getBoundingClientRect();
        const aRect = activeEl.getBoundingClientRect();
        const delta =
          aRect.left - cRect.left - (container.clientWidth - aRect.width) / 2;
        container.scrollTo({
          left: container.scrollLeft + delta,
          behavior: "smooth",
        });
      }
      setIndicatorStyle({
        left: activeEl.offsetLeft,
        width: activeEl.offsetWidth,
      });
    }
  }, [activeSection, menuItems]);

  const handleClick = (
    e: React.MouseEvent<HTMLAnchorElement>,
    href: string
  ) => {
    e.preventDefault();
    const el = document.getElementById(href.replace("#", ""));
    if (el) {
      // Header artık tur sayfasında sticky değil; tek sabit eleman bu menü
      // çubuğu. Offset'i çubuğun gerçek yüksekliğine göre hesapla ki bölüm
      // başlığı menünün altında kalmasın.
      const menuHeight = navRef.current?.offsetHeight ?? 56;
      window.scrollTo({
        top: el.getBoundingClientRect().top + window.scrollY - menuHeight - 12,
        behavior: "smooth",
      });
    }
  };

  if (menuItems.length === 0) return null;

  return (
    <>
      <div ref={sentinelRef} style={{ height: 1 }} />

      <div
        className={[
          "tw-top-0 tw-z-40 tw-bg-white tw-min-w-0 tw-w-full tw-relative",
          isSticky ? "tw-sticky" : "",
        ].join(" ")}
      >
        <div
          ref={scrollRef}
          className={`${styles.scrollHide} tw-border-b tw-border-gray-200 tw-overflow-x-auto tw-px-1 sm:tw-px-0`}
          style={{ WebkitOverflowScrolling: "touch" }}
        >
          <nav
            ref={navRef}
            className={`${styles.scrollHide} tw-flex tw-items-end tw-justify-start tw-overflow-x-auto tw-relative tw-w-max tw-min-w-full md:tw-min-w-0 tw-pr-4 md:tw-pr-0`}
            style={{ WebkitOverflowScrolling: "touch" }}
          >
            <div
              className="tw-absolute tw-bottom-[0px] tw-h-[3px] tw-bg-primary tw-rounded-full tw-transition-all tw-duration-300 tw-ease-out"
              style={{
                left: `${indicatorStyle.left}px`,
                width: `${indicatorStyle.width}px`,
              }}
            />

            {menuItems.map((item) => {
              const id = item.href.replace("#", "");
              const isActive = activeSection === id;

              return (
                <a
                  key={item.label}
                  href={item.href}
                  data-section={id}
                  onClick={(e) => handleClick(e, item.href)}
                  style={{ textDecoration: "none" }}
                  className={[
                    "tw-relative tw-flex-shrink-0 tw-select-none tw-text-center",
                    "tw-px-3 tw-py-3.5 sm:tw-px-4 md:tw-px-6 md:tw-pt-5 md:tw-pb-4",
                    "tw-text-[14px] sm:tw-text-[15px] md:tw-text-base tw-whitespace-nowrap",
                    "tw-transition-colors tw-duration-300 tw-ease-in-out",
                    isActive
                      ? "tw-text-primary tw-font-medium"
                      : "tw-font-normal tw-text-gray-700 hover:tw-text-primary/80",
                  ].join(" ")}
                >
                  {item.label}
                </a>
              );
            })}
          </nav>
        </div>
        <div
          className="tw-absolute tw-left-0 tw-right-0 tw-top-full tw-pointer-events-none tw-h-3"
          style={{
            background: "linear-gradient(to bottom, rgba(0,0,0,0.06), transparent)",
            WebkitMaskImage: "linear-gradient(to right, transparent 0%, black 12%, black 88%, transparent 100%)",
            maskImage: "linear-gradient(to right, transparent 0%, black 12%, black 88%, transparent 100%)",
          }}
          aria-hidden
        />
      </div>
    </>
  );
};

export default Menu;
