"use client";
import React from "react";
import { useTourModals } from "./tour-modals-context";
import { outlineBtnCls } from "./ui";

const CheckMark = () => (
  <span className="tw-shrink-0 tw-flex tw-h-7 tw-w-7 tw-items-center tw-justify-center tw-rounded-full tw-bg-[#854ec9] tw-text-white">
    <svg
      width="15"
      height="15"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={3}
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <path d="M5 13l4 4L19 7" />
    </svg>
  </span>
);

const Tailormaid = ({ goodToKnow }: any) => {
  const { openInquiry } = useTourModals();

  const Benefit = ({ title, text }: { title: string; text: string }) => (
    <div className="tw-flex tw-gap-3">
      <CheckMark />
      <div>
        <h4 className="tw-m-0 tw-text-[15px] tw-font-semibold tw-text-[#14101c]">
          {title}
        </h4>
        <p className="tw-mt-1 tw-mb-0 tw-text-[14px] tw-text-[#5d556c]">{text}</p>
      </div>
    </div>
  );

  return (
    <div className="tw-my-6 tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-[#faf8fd] tw-p-6 md:tw-p-8">
      <h3 className="tw-font-display tw-m-0 tw-text-[22px] tw-font-bold tw-tracking-tight tw-text-[#14101c]">
        Make this journey exclusively yours
      </h3>
      <p className="tw-mt-3 tw-mb-0 tw-max-w-[72ch] tw-text-[#5d556c]">
        By design, this is a group tour. You can however request a private,
        customized version of this tour for yourself or your private group of
        people. Private departures are usually more expensive, but come with
        these benefits:
      </p>

      <div className="tw-mt-6 tw-grid sm:tw-grid-cols-2 tw-gap-x-8 tw-gap-y-5">
        <Benefit
          title="Personal"
          text="Itinerary can be tweaked and customized."
        />
        <Benefit title="Protected" text="Travel withing your own bubble." />
        <Benefit
          title="Professional"
          text="Access our Travel Specialists insider knowledge."
        />
        <Benefit
          title="Privacy"
          text="Enjoy a tour focused solely on you or your travel group."
        />
      </div>

      <button
        className={`${outlineBtnCls} tw-mt-7 tw-font-bold`}
        type="button"
        onClick={openInquiry}
      >
        Request a private and/or personalized departure
      </button>
    </div>
  );
};

export default Tailormaid;
