"use client";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { getCookie, hasCookie } from "cookies-next";
import getTourAvailability from "@/services/tourAvailability";
import getTourAvailabilityMonths from "@/services/tourAvailabilityMonths";
import Breadcrumb from "../header/breadcrumb";
import PriceSide from "./price-side/price-side";
import PriceSideSkeleton from "./price-side/skeleton";
import { TourModalsProvider, useTourModals } from "./tour-modals-context";
import { darkBtnCls, outlineBtnCls } from "./ui";
import MobileFooterSticky from "./mobile-footer-sticky";
import Availability from "./availability/availability";
import HeaderSection from "./header-section";
import Reviews from "./reviews";
import Tailormaid from "./tailormaid";
import Menu from "./menu";
import Places from "./places";
import Info from "./info";
import Overview from "./overview";
import Includes from "./includes";
import Itineraries from "./itineraries";
import WhyBook from "./why-book";
import GoodToKnow from "./good-to-know";
import Highlights from "./highlights";
import SimilarTours from "./similar-tours";
import SupplierCard from "./supplier-card";
import Route from "./route";
import getComission from "@/helpers/calcComission";
import cdnImage from "@/helpers/cdnImage";
import Gallery from "./gallery";
import GalleryMobil from "./gallery-mobil";
import Lightbox from "yet-another-react-lightbox";
import Slideshow from "yet-another-react-lightbox/plugins/slideshow";
import Thumbnails from "yet-another-react-lightbox/plugins/thumbnails";
import Zoom from "yet-another-react-lightbox/plugins/zoom";
import Counter from "yet-another-react-lightbox/plugins/counter";
import "yet-another-react-lightbox/plugins/thumbnails.css";
import "yet-another-react-lightbox/plugins/counter.css";
import "yet-another-react-lightbox/styles.css";
import Ratings from "@/components/tour-detail-page/rating";
import ProductSchema from "./product-schema";
import GallerySingle from "./gallery-single";
import CancelRefundIcon from "../icons/CancelRefundIcon";
import EarlyBookingIcon from "../icons/EarlyBookingIcon";

// Page-level trigger buttons. Defined as separate components so they render
// *inside* TourModalsProvider and can consume the modal context.
function AskQuestionButton() {
  const { openInquiry } = useTourModals();
  return (
    <button
      className={`${darkBtnCls} tw-w-full md:tw-w-auto`}
      type="button"
      onClick={openInquiry}
    >
      Ask a Question
    </button>
  );
}

function BrochureButton() {
  const { openBrochure } = useTourModals();
  return (
    <button
      className={`${outlineBtnCls} tw-w-full`}
      type="button"
      onClick={openBrochure}
    >
      <svg
        xmlns="http://www.w3.org/2000/svg"
        width="20"
        height="20"
        fill="currentColor"
        className="tw-mr-2"
        viewBox="0 0 16 16"
      >
        <path d="M14 4.5V14a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V2a2 2 0 0 1 2-2h5.5zm-3 0A1.5 1.5 0 0 1 9.5 3V1H4a1 1 0 0 0-1 1v12a1 1 0 0 0 1 1h8a1 1 0 0 0 1-1V4.5z" />
        <path d="M4.5 12.5A.5.5 0 0 1 5 12h3a.5.5 0 0 1 0 1H5a.5.5 0 0 1-.5-.5m0-2A.5.5 0 0 1 5 10h6a.5.5 0 0 1 0 1H5a.5.5 0 0 1-.5-.5m1.639-3.708 1.33.886 1.854-1.855a.25.25 0 0 1 .289-.047l1.888.974V8.5a.5.5 0 0 1-.5.5H5a.5.5 0 0 1-.5-.5V8s1.54-1.274 1.639-1.208M6.25 6a.75.75 0 1 0 0-1.5.75.75 0 0 0 0 1.5" />
      </svg>{" "}
      Download Brochure
    </button>
  );
}

export default function TourDetailPage({
  tourData,
  breadcrumb,
}: {
  tourData: any;
  breadcrumb: any;
}) {
  const [availabilityLoading, setAvailabilityLoading] = useState(true);
  const [availabilityPriceLoading, setAvailabilityPriceLoading] =
    useState(true);
  const [prices, setPrices] = useState({});
  const [isUser, setIsUser] = useState(false);
  const [showPriceSide, setShowPriceSide] = useState(true);
  const [comission, setComission] = useState({
    regularPriceCreditPoint: 0,
    privatePriceCreditPoint: 0,
    totalCreditPoint: 0,
  });
  const [departureMonths, setDepartureMonths] = useState([]);
  const [availabilityFilters, setAvailabilityFilters] = useState({
    serviceType: "",
    travelers:
      tourData.groupSizeMin === 0 || tourData.groupSizeMin === 1
        ? tourData.groupSizeMax >= 3
          ? 3
          : tourData.groupSizeMax
        : tourData.groupSizeMin,
    departureMonth: "",
  });
  const isInitialMount = useRef(true);

  // Memoised so its reference is stable across re-renders (e.g. after the
  // availability fetch) — otherwise the mobile gallery (Swiper) re-initialises
  // and the image flickers/disappears.
  const tourImages = useMemo(
    () =>
      (tourData.media || [])
        .map((item: any) => {
          const url = item.high || item.main || "";
          return url ? { imageUrl: url } : null;
        })
        .filter(Boolean) as { imageUrl: string }[],
    [tourData.media]
  );

  const [lightBoxIndex, setLightBoxIndex] = useState(-1);
  const handleLightBox = useCallback((index: any) => {
    setLightBoxIndex(index);
  }, []);

  const fetchAvailabilityDates = () => {
    setAvailabilityPriceLoading(true);
    getTourAvailability({
      tourSlug: tourData.slug,
      date: availabilityFilters.departureMonth,
      pax: availabilityFilters.travelers,
      activeCurrency: getCookie("currency"),
      serviceType: null,
    }).then((availabilityRes) => {
      setPrices(availabilityRes);
      setShowPriceSide(
        availabilityRes.is_regular || availabilityRes.is_private,
      );

      const comissionCalc = getComission({
        regularPrice:
          availabilityRes.is_regular && availabilityRes.regular_price > 0
            ? availabilityRes.regular_price
            : 0,
        privatePrice:
          availabilityRes.is_private && availabilityRes.private_price > 0
            ? availabilityRes.private_price
            : 0,
      });

      setComission(comissionCalc);
      setAvailabilityLoading(false);
      setAvailabilityPriceLoading(false);
    });
  };

  useEffect(() => {
    if (hasCookie("user-role")) setIsUser(true);

    getTourAvailabilityMonths({
      tourId: tourData.id,
    }).then((monthsRes) => {
      if (monthsRes.length > 0) {
        const clearMonthsRes = monthsRes.filter(
          (item: any, index: number) => monthsRes.indexOf(item) === index,
        );
        setDepartureMonths(clearMonthsRes);
        setAvailabilityFilters({
          ...availabilityFilters,
          departureMonth: monthsRes[0],
        });
      } else {
        setShowPriceSide(false);
        setAvailabilityLoading(false);
        setAvailabilityPriceLoading(false);
      }
    });
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    if (isInitialMount.current) isInitialMount.current = false;
    else fetchAvailabilityDates();
  }, [availabilityFilters.departureMonth, availabilityFilters.travelers]); // eslint-disable-line react-hooks/exhaustive-deps

  return (
    <TourModalsProvider tourId={tourData.id} tourSlug={tourData.slug}>
      <main>
        <div className="tw-mx-auto tw-max-w-[1320px] tw-px-4 tw-my-6">
          <ProductSchema tourData={tourData} />
          <Breadcrumb
            items={[
              ...breadcrumb,
              { pageTitle: tourData.name, pageUrl: `/tour/${tourData.slug}` },
            ]}
          />
          <div className="tw-flex tw-flex-wrap">
            <div className="tw-w-full">
              <HeaderSection
                tourData={tourData}
                availabilityLoading={availabilityLoading}
                prices={prices}
              />
            </div>

            {tourImages.length > 1 && (
              <>
                <Gallery
                  images={tourImages}
                  tourName={tourData.name}
                  onLightBoxIndexChange={handleLightBox}
                />
                <GalleryMobil
                  images={tourImages}
                  tourName={tourData.name}
                  onLightBoxIndexChange={handleLightBox}
                />
              </>
            )}

            <div className="tw-w-full lg:tw-w-2/3 lg:tw-pr-4">
              <div>
                {tourImages.length == 1 && (
                  <GallerySingle
                    images={tourImages}
                    tourName={tourData.name}
                    onLightBoxIndexChange={handleLightBox}
                  />
                )}
                <div className="lg:tw-hidden tw-mt-2 tw-mb-4">
                  <div className="tw-flex tw-flex-col">
                    <div
                      className="tw-flex tw-items-center tw-gap-3 tw-p-1 tw-rounded-xl tw-bg-white"
                      style={{ minHeight: 56 }}
                    >
                      <span
                        className="tw-flex tw-items-center tw-justify-center tw-rounded-full"
                        style={{
                          width: 40,
                          height: 40,
                          background: "#F5F6F7",
                        }}
                      >
                        <CancelRefundIcon />
                      </span>
                      <div>
                        <div className="tw-font-semibold tw-text-base tw-text-[#14101c] tw-mb-1">
                          Free Cancellation
                        </div>
                        <div className="tw-text-[#5d556c] tw-text-sm">
                          Full refund up to 30 days before the tour
                        </div>
                      </div>
                    </div>
                    <div
                      className="tw-flex tw-items-center tw-gap-3 tw-p-2 tw-rounded-xl tw-bg-white"
                      style={{ minHeight: 56 }}
                    >
                      <span
                        className="tw-flex tw-items-center tw-justify-center tw-rounded-full"
                        style={{
                          width: 40,
                          height: 40,
                          background: "#F5F6F7",
                        }}
                      >
                        <EarlyBookingIcon />
                      </span>
                      <div>
                        <div className="tw-font-semibold tw-text-base tw-text-[#14101c] tw-mb-1">
                          Early Booking Advantage
                        </div>
                        <div className="tw-text-[#5d556c] tw-text-sm">
                          Only 25% prepayment until 30 days before departure
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
                <Info tourData={tourData} />
                <Menu tourData={tourData} />
                <Overview tourData={tourData} />
                <Route tourData={tourData} />
                <Places tourData={tourData} />
                <Highlights tourData={tourData} />
                <Itineraries tourData={tourData} />
                <Includes tourData={tourData} />
                <Availability
                  departureMonths={departureMonths}
                  slug={tourData.slug}
                  tourId={tourData.id}
                  prices={prices}
                  accommodation={tourData.defaults.accommodation}
                  groupSizeMin={tourData.groupSizeMin}
                  groupSizeMax={tourData.groupSizeMax}
                  availabilityLoading={availabilityLoading}
                  availabilityPriceLoading={availabilityPriceLoading}
                  availabilityFilters={availabilityFilters}
                  availabilityFilterChange={(filters: any) => {
                    setAvailabilityFilters(filters);
                  }}
                />
                <Reviews tourData={tourData} />
                <Tailormaid goodToKnow="goodToKnow" />
                <WhyBook />
                <Ratings
                  tourID={tourData.id}
                  modalOnly={false}
                  updatableReview={null}
                />
                <GoodToKnow />
                <SupplierCard company={tourData.company} />
                <div
                  className="tw-mt-6 tw-rounded-2xl tw-border tw-border-solid tw-border-[#e7dcf6] tw-bg-[#f4eefb] tw-p-6 md:tw-p-8"
                  id="goodToKnow"
                >
                  <div className="tw-flex tw-flex-col md:tw-flex-row md:tw-items-center md:tw-justify-between tw-gap-5">
                    <div className="tw-flex tw-items-start tw-gap-4">
                      <span className="tw-shrink-0 tw-flex tw-h-12 tw-w-12 tw-items-center tw-justify-center tw-rounded-full tw-bg-white tw-text-[#854ec9]">
                        <svg
                          xmlns="http://www.w3.org/2000/svg"
                          width="22"
                          height="22"
                          fill="currentColor"
                          viewBox="0 0 16 16"
                        >
                          <path d="M8 1a5 5 0 0 0-5 5v1h1a1 1 0 0 1 1 1v3a1 1 0 0 1-1 1H3a1 1 0 0 1-1-1V6a6 6 0 1 1 12 0v6a2.5 2.5 0 0 1-2.5 2.5H9.366a1 1 0 0 1-.866.5h-1a1 1 0 1 1 0-2h1a1 1 0 0 1 .866.5H11.5A1.5 1.5 0 0 0 13 12h-1a1 1 0 0 1-1-1V8a1 1 0 0 1 1-1h1V6a5 5 0 0 0-5-5z" />
                        </svg>
                      </span>
                      <div>
                        <h3 className="tw-font-display tw-m-0 tw-text-[20px] tw-font-bold tw-text-[#14101c]">
                          Need help or have a question about this tour?
                        </h3>
                        <p className="tw-mt-2 tw-mb-0 tw-text-[#5d556c]">
                          if you have any question about this tour or need help
                          with planning a trip, please do not hesitate to get in
                          touch with us. We&apos;re ready to help.
                        </p>
                      </div>
                    </div>
                    <div className="tw-shrink-0 tw-w-full md:tw-w-auto">
                      <AskQuestionButton />
                    </div>
                  </div>
                </div>
              </div>
            </div>
            <div
              className="tw-w-full lg:tw-w-1/3 tw-hidden lg:tw-block"
              style={{ zIndex: 0 }}
            >
              <div className="tw-sticky" style={{ top: "30px" }}>
                <div className="tw-rounded-xl tw-border tw-border-solid tw-border-[#ebe7f0] tw-shadow-sm tw-p-4">
                  {availabilityLoading ? (
                    <PriceSideSkeleton />
                  ) : (
                    <PriceSide
                      prices={prices}
                      comission={comission}
                      departureType={tourData.departure_type_id}
                      tourData={tourData}
                    />
                  )}
                </div>

                <div className="tw-my-6 tw-px-1">
                  <BrochureButton />
                </div>
              </div>
            </div>
          </div>

          <SimilarTours
            destination={tourData.startLocationSlug}
            category={tourData.category.slug}
          />
        </div>
        <MobileFooterSticky
          prices={prices}
          departureType={tourData.departure_type_id}
          availabilityLoading={availabilityLoading}
        />
        <Lightbox
          slides={tourImages.map(({ imageUrl }: { imageUrl: any }) => ({
            src: cdnImage(imageUrl),
          }))}
          controller={{ closeOnBackdropClick: true }}
          index={lightBoxIndex}
          open={lightBoxIndex >= 0}
          close={() => setLightBoxIndex(-1)}
          counter={{ container: { style: { top: 0 } } }}
          plugins={[Slideshow, Thumbnails, Zoom, Counter]}
        />
      </main>
    </TourModalsProvider>
  );
}
