"use client";
import priceFormat from "@/helpers/priceFormat";
import { getCookie } from "cookies-next";
import CancelRefundIcon from "@/components/icons/CancelRefundIcon";
import EarlyBookingIcon from "@/components/icons/EarlyBookingIcon";
import getPrice from "@/helpers/getLastPrice";
import { useTourModals } from "../tour-modals-context";
import { primaryBtnCls, darkBtnCls } from "../ui";
import WishlistButton from "@/components/wishlist/wishlist-button";

export default function PriceSide({
  prices,
  comission,
  departureType,
  tourData,
}: {
  prices: any;
  comission: any;
  departureType: string;
  tourData: any;
}) {
  const { openInquiry } = useTourModals();

  const wishlistTour = {
    id: tourData.id,
    slug: tourData.slug,
    name: tourData.name,
    image:
      tourData?.media?.find((m: any) => m.main)?.main ??
      tourData?.media?.[0]?.high,
  };

  const priceDetail = getPrice({
    isRegular: prices.is_regular,
    regularPrice: prices.regular_price,
    oldRegularPrice: prices.old_regular_price,
    isPrivate: prices.is_private,
    privatePrice: prices.private_price,
    oldPrivatePrice: prices.old_private_price,
    rooms: prices.rooms,
  });

  const questionIcon = (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width="18"
      height="18"
      fill="currentColor"
      className="tw-mr-2"
      viewBox="0 0 16 16"
    >
      <path d="M8 15A7 7 0 1 1 8 1a7 7 0 0 1 0 14m0 1A8 8 0 1 0 8 0a8 8 0 0 0 0 16" />
      <path d="M5.255 5.786a.237.237 0 0 0 .241.247h.825c.138 0 .248-.113.266-.25.09-.656.54-1.134 1.342-1.134.686 0 1.314.343 1.314 1.168 0 .635-.374.927-.965 1.371-.673.489-1.206 1.06-1.168 1.987l.003.217a.25.25 0 0 0 .25.246h.811a.25.25 0 0 0 .25-.25v-.105c0-.718.273-.927 1.01-1.486.609-.463 1.244-.977 1.244-2.056 0-1.511-1.276-2.241-2.673-2.241-1.267 0-2.655.59-2.75 2.286m1.557 5.763c0 .533.425.927 1.01.927.609 0 1.028-.394 1.028-.927 0-.552-.42-.94-1.029-.94-.584 0-1.009.388-1.009.94" />
    </svg>
  );

  if (!prices.is_regular && !prices.is_private)
    return (
      <div>
        <div className="tw-flex tw-justify-end">
          <WishlistButton
            variant="icon"
            className="tw-shrink-0"
            tour={wishlistTour}
          />
        </div>
        <p className="tw-mb-6 tw-mt-1 tw-text-center tw-font-bold tw-text-[#854ec9]">
          Ask for the price and more.
        </p>

        <div className="tw-flex tw-mt-4 tw-justify-between tw-gap-2">
          <button
            className={`${darkBtnCls} tw-w-full`}
            type="button"
            onClick={openInquiry}
          >
            {questionIcon}
            Ask a Question
          </button>
        </div>
      </div>
    );

  return (
    <div>
      <div className="tw-mb-2 tw-flex tw-items-center tw-justify-between tw-gap-2 tw-min-h-[28px]">
        {departureType === "guaranteed" ? (
          <span className="tw-text-[14px] tw-font-semibold tw-text-[#198754]">
            Guaranteed departure!
          </span>
        ) : (
          <span />
        )}
        <WishlistButton
          variant="icon"
          className="tw-shrink-0"
          tour={wishlistTour}
        />
      </div>
      {priceDetail.price > 0 && (
        <div className="tw-text-center tw-mt-4">
          <small className="tw-text-sm">
            From{" "}
            {priceDetail.oldPrice > 0 &&
              priceDetail.price != priceDetail.oldPrice && (
                <>
                  <span className="tw-line-through tw-text-base">
                    {priceFormat({
                      amount: priceDetail.oldPrice,
                      currency: getCookie("currency"),
                    })}
                  </span>{" "}
                  <span className="tw-inline-flex tw-items-center tw-rounded tw-bg-[#dc3545] tw-text-white tw-px-2 tw-py-0.5 tw-text-[12px] tw-font-semibold">
                    {"-" +
                      (
                        ((priceDetail.oldPrice - priceDetail.price) /
                          priceDetail.oldPrice) *
                        100
                      ).toFixed(0) +
                      "%"}
                  </span>
                </>
              )}
          </small>
          <br />
          <span>
            <span className="tw-text-[28px] tw-font-bold tw-text-[#14101c]">
              {priceFormat({
                amount: priceDetail.price,
                currency: getCookie("currency"),
              })}{" "}
            </span>
            <br />
            <small className="tw-text-sm tw-text-[#5d556c]">
              {priceDetail.priceDesc}
            </small>
          </span>
          {priceDetail.oldPrice > 0 &&
            priceDetail.price != priceDetail.oldPrice &&
            (prices.availability?.promotionDetail?.pax_left ?? 0) > 0 && (
              <p className="tw-m-0 tw-font-bold tw-text-[#dc3545]">
                <small className="tw-text-sm">
                  {(prices.availability?.promotionDetail?.pax_left ?? 0)} pax left
                </small>
              </p>
            )}
        </div>
      )}

      {/* Ücretsiz iptal ve erken rezervasyon kartları - Minimal ve şık, gölgesiz ve daha yakın */}
      <div className="tw-my-6">
        <div className="tw-flex tw-flex-col">
          <div
            className="tw-flex tw-items-center tw-gap-3 tw-p-2 tw-rounded-xl tw-bg-white"
            style={{ minHeight: 56 }}
          >
            <span
              className="tw-flex tw-items-center tw-justify-center tw-rounded-full"
              style={{ width: 40, height: 40, background: "#F5F6F7" }}
            >
              <CancelRefundIcon />
            </span>
            <div>
              <div className="tw-font-semibold tw-text-base tw-text-[#14101c] tw-mb-1">
                Free Cancellation
              </div>
              <div className="tw-text-[#5d556c] tw-text-sm">
                Full refund up to 30 days before the tour
              </div>
            </div>
          </div>
          <div
            className="tw-flex tw-items-center tw-gap-3 tw-p-2 tw-rounded-xl tw-bg-white"
            style={{ minHeight: 56 }}
          >
            <span
              className="tw-flex tw-items-center tw-justify-center tw-rounded-full"
              style={{ width: 40, height: 40, background: "#F5F6F7" }}
            >
              <EarlyBookingIcon />
            </span>
            <div>
              <div className="tw-font-semibold tw-text-base tw-text-[#14101c] tw-mb-1">
                Early Booking Advantage
              </div>
              <div className="tw-text-[#5d556c] tw-text-sm">
                Only 25% prepayment until 30 days before departure
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="tw-flex tw-mt-4 tw-justify-between tw-gap-2">
        <a href="#availability" className={`${primaryBtnCls} tw-w-full`}>
          Check Availability
        </a>
        <button
          className={`${darkBtnCls} tw-w-full`}
          type="button"
          onClick={openInquiry}
        >
          {questionIcon}
          Ask a Question
        </button>
      </div>
    </div>
  );
}
