type CompanyCard = {
  id: number;
  name: string;
};

/**
 * Tur detayında turu işleten şirketi gösteren sade tek satır: üstte ince ayraç
 * çizgisi + "This tour is provided by {şirket}". (Şimdilik linksiz düz metin.)
 * company yoksa hiç render edilmez. Veri tur cache'indeki company.name'den gelir.
 */
export default function SupplierCard({ company }: { company: { name?: string } | null }) {
  if (!company || !company.name) return null;

  return (
    <div className="tw-mt-6 tw-border-0 tw-border-t tw-border-solid tw-border-[#ece9f1] tw-pt-4 tw-text-sm tw-text-[#5d556c]">
      This tour is provided by{" "}
      <span className="tw-font-semibold tw-text-[#14101c]">{company.name}</span>
    </div>
  );
}
