export default function ProductSchema({ tourData }: { tourData: any }) {
  const reviews: any[] = tourData.reviews ?? [];
  if (reviews.length === 0) return null;

  function stripHtml(html: string) {
    return html.replace(/<[^>]*>?/gm, "");
  }

  function getShortDescription(text: string, idealLength = 300, maxLength = 350) {
    if (!text || text.length <= idealLength) return text;
    
    const limitText = text.substring(0, maxLength);
    const lastPeriodIndex = limitText.lastIndexOf(".", maxLength);

    if (lastPeriodIndex > idealLength - 100) {
      return limitText.substring(0, lastPeriodIndex + 1);
    }
    
    const lastSpaceIndex = limitText.lastIndexOf(" ", maxLength);
    if (lastSpaceIndex > 0) {
      return limitText.substring(0, lastSpaceIndex) + "...";
    }

    return limitText + "...";
  }

  const averageRating = tourData.rating;
  const reviewCount = tourData.review_count;

  const aggregateRating =
    averageRating > 0 && reviewCount > 0
      ? {
          "@type": "AggregateRating",
          ratingValue: averageRating,
          bestRating: 5,
          worstRating: 1,
          ratingCount: reviewCount,
        }
      : undefined;

  const reviewItems =
    reviews.length > 0
      ? reviews.slice(0, 5).map((r: any) => ({
          "@type": "Review",
          reviewRating: {
            "@type": "Rating",
            ratingValue: r.rating,
            bestRating: 5,
            worstRating: 1,
          },
          author: {
            "@type": "Person",
            name: r.customer_display_name,
          },
          reviewBody: r.content,
        }))
      : undefined;

  const mainImage =
    tourData.media?.find((m: any) => m.main)?.main ??
    tourData.media?.[0]?.high ??
    undefined;

  const rawDescription = stripHtml(tourData.description ?? "").trim();
  const description = getShortDescription(rawDescription);

  const jsonLd: Record<string, any> = {
    "@context": "https://schema.org/",
    "@type": "Product",
    name: tourData.name,
    description,
    image: mainImage,
    sku: tourData.slug,
    brand: {
      "@type": "Brand",
      name: "TravelShop Booking",
    },
    url: "https://travelshopbooking.com/tour/" + tourData.slug,
  };

  if (reviewItems && reviewItems.length > 0) jsonLd.review = reviewItems;
  if (aggregateRating) jsonLd.aggregateRating = aggregateRating;

  return (
    <script
      type="application/ld+json"
      dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }}
    />
  );
}
