"use client";
import priceFormat from "@/helpers/priceFormat";
import { getCookie } from "cookies-next";
import hasDeposit from "@/helpers/hasDeposit";
import getPrice from "./priceSelector";
import { useState, useEffect } from "react";
import { primaryBtnCls } from "../ui";
import { formatPlainDate } from "@/helpers/plainDate";

const VISIBLE_LIMIT = 5;

export default function Departures({
  data,
  slug,
  serviceType,
  accommodation,
  travelers,
}: {
  data: any;
  slug: string;
  serviceType: any;
  accommodation: any;
  travelers: any;
}) {
  const [roomDetailDate, setRoomDetailDate] = useState(null);
  const [showAll, setShowAll] = useState(false);

  useEffect(() => {
    if (
      Array.isArray(data?.prices) &&
      data.prices.length > 0 &&
      Array.isArray(data.prices[0]?.dates) &&
      data.prices[0].dates.length > 0
    ) {
      setRoomDetailDate(data.prices[0].dates[0].start);
    }
  }, [data]);

  // Reset the collapsed state whenever the underlying departures change.
  useEffect(() => {
    setShowAll(false);
  }, [serviceType, travelers, data]);

  // Tarih saat dilimi kaymasına karşı güvenli biçimlendirilir (bkz. helpers/plainDate.ts).
  const getFullDate = (date: string) => formatPlainDate(date);

  // Flatten all priced departures so we can cap the visible count.
  const departures = (data.prices || [])
    .flatMap((item: any) =>
      (item.dates || []).map((date: any) => {
        const priceDetail = getPrice({
          accommodation,
          prices:
            serviceType == "regular" ? date.prices.regular : date.prices.private,
          travelers,
        });
        return { date, priceDetail };
      })
    )
    .filter((d: any) => d.priceDetail.price > 0);

  const hiddenCount = departures.length - VISIBLE_LIMIT;
  const visible =
    showAll || departures.length <= VISIBLE_LIMIT
      ? departures
      : departures.slice(0, VISIBLE_LIMIT);

  return (
    <div className="tw-mt-6">
      <p className="tw-text-[18px] tw-font-semibold tw-text-[#14101c] tw-mb-4">
        {serviceType === "regular" ? "Group Tour" : "Private Tour"} Departures
      </p>
      {visible.map(({ date, priceDetail }: any) => {
        const price = priceDetail.price;
        const oldPrice = priceDetail.oldPrice;
        const subTitle = priceDetail.subTitle;

        return (
          <div
            className="tw-relative tw-mt-6 tw-rounded-xl tw-border tw-border-solid tw-border-[#ebe7f0] tw-shadow-sm"
            key={date.start}
          >
            {hasDeposit(date.start) && (
              <span className="tw-absolute tw-top-0 tw-right-0 tw--translate-y-1/2 tw-bg-[#198754] tw-text-white tw-rounded tw-px-2 tw-py-1 tw-text-[12px] tw-font-semibold">
                Now, just deposit 25% of the total
              </span>
            )}

            <div className="tw-p-4">
              <div className="tw-grid tw-grid-cols-3 md:tw-grid-cols-4 tw-gap-y-3 md:tw-gap-y-0 tw-items-center">
                <div className="tw-self-center">
                  <small>
                    <strong>STARTS</strong>
                  </small>
                  <br />
                  {getFullDate(date.start)}
                </div>
                <div className="tw-self-center">
                  <small>
                    <strong>ENDS</strong>
                  </small>
                  <br />
                  {getFullDate(date.end)}
                </div>
                <div className="tw-self-center tw-text-center">
                  {oldPrice > 0 && price !== oldPrice && (
                    <>
                      <small>
                        <span className="tw-line-through">
                          {priceFormat({
                            amount: oldPrice,
                            currency: getCookie("currency"),
                          })}
                        </span>{" "}
                        <span className="tw-inline-flex tw-items-center tw-rounded tw-bg-[#dc3545] tw-text-white tw-px-2 tw-py-0.5 tw-text-[12px] tw-font-semibold">
                          {"-" +
                            (
                              ((priceDetail.oldPrice - priceDetail.price) /
                                priceDetail.oldPrice) *
                              100
                            ).toFixed(0) +
                            "%"}
                        </span>
                      </small>
                      <br />
                    </>
                  )}
                  <span className="tw-text-[18px] tw-font-bold tw-text-[#14101c]">
                    {priceFormat({
                      amount: price,
                      currency: getCookie("currency"),
                    })}
                  </span>
                  <br />
                  <small className="tw-text-[#5d556c]">{subTitle}</small>
                </div>
                <div className="tw-col-span-3 md:tw-col-span-1 tw-self-center tw-text-center">
                  <button
                    type="button"
                    className={`${primaryBtnCls} tw-w-full`}
                    role="button"
                    onClick={(event) => {
                      event.preventDefault();
                      window.open(
                        `/checkout?slug=${slug}&date=${date.start}&service-type=${serviceType}&pax=${travelers}`,
                        "_blank"
                      );
                    }}
                  >
                    Book Now
                  </button>
                  {data.rooms.length > 0 && (
                    <button
                      type="button"
                      className="tw-inline-flex tw-items-center tw-justify-center tw-gap-1 tw-w-full tw-mt-1 tw-bg-transparent tw-border-0 tw-text-[#14101c] tw-no-underline tw-cursor-pointer"
                      role="button"
                      onClick={() => {
                        if (roomDetailDate && roomDetailDate == date.start)
                          setRoomDetailDate(null);
                        else setRoomDetailDate(date.start);
                      }}
                    >
                      <svg
                        xmlns="http://www.w3.org/2000/svg"
                        width="24"
                        height="24"
                        fill="currentColor"
                        viewBox="0 0 16 16"
                      >
                        <path d="M3 14.5A1.5 1.5 0 0 1 1.5 13V3A1.5 1.5 0 0 1 3 1.5h8a.5.5 0 0 1 0 1H3a.5.5 0 0 0-.5.5v10a.5.5 0 0 0 .5.5h10a.5.5 0 0 0 .5-.5V8a.5.5 0 0 1 1 0v5a1.5 1.5 0 0 1-1.5 1.5z" />
                        <path d="m8.354 10.354 7-7a.5.5 0 0 0-.708-.708L8 9.293 5.354 6.646a.5.5 0 1 0-.708.708l3 3a.5.5 0 0 0 .708 0" />
                      </svg>{" "}
                      Room Options
                    </button>
                  )}
                </div>
              </div>
              {roomDetailDate &&
                roomDetailDate == date.start &&
                data.rooms.length > 0 && (
                  <div className="tw-mt-2 tw-border-0 tw-border-t tw-border-solid tw-border-[#ebe7f0]">
                    <div>
                      {data.rooms.map((room: any) => {
                        var roomPrice =
                          data.prices?.[0]?.dates?.find(
                            (item: any) => item.start == date.start
                          )?.prices?.[serviceType] ?? {};
                        return (
                          <div
                            className="tw-grid tw-grid-cols-12 tw-items-center tw-gap-2 tw-mt-6"
                            key={room.id}
                          >
                            <div className="tw-col-span-12 md:tw-col-span-6">
                              <strong>{room.name}</strong>
                              <p>{room.desc}</p>
                            </div>
                            <div className="tw-col-span-4 md:tw-col-span-2">
                              {roomPrice["old_" + room.id] > 0 &&
                                roomPrice[room.id] !==
                                  roomPrice["old_" + room.id] && (
                                  <small>
                                    <span className="tw-line-through tw-text-[#dc3545]">
                                      {priceFormat({
                                        amount: roomPrice["old_" + room.id],
                                        currency: getCookie("currency"),
                                      })}
                                    </span>
                                    <br />
                                  </small>
                                )}
                              <strong>
                                {priceFormat({
                                  amount: roomPrice[room.id],
                                  currency: getCookie("currency"),
                                })}
                              </strong>
                            </div>
                            <div className="tw-col-span-8 md:tw-col-span-4">
                              {" "}
                              <button
                                type="button"
                                className={`${primaryBtnCls} tw-w-full`}
                                role="button"
                                onClick={(event) => {
                                  event.preventDefault();
                                  window.open(
                                    `/checkout?slug=${slug}&date=${date.start}&service-type=${serviceType}&pax=${travelers}`,
                                    "_blank"
                                  );
                                }}
                              >
                                Book Now
                              </button>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                )}
            </div>
          </div>
        );
      })}

      {departures.length > VISIBLE_LIMIT && (
        <div className="tw-mt-6 tw-text-center">
          <button
            type="button"
            onClick={() => setShowAll((v) => !v)}
            className="tw-inline-flex tw-items-center tw-justify-center tw-gap-2 tw-px-5 tw-py-2.5 tw-rounded-full tw-bg-white hover:tw-bg-[#faf9fc] tw-text-[#854ec9] tw-text-[14px] tw-font-semibold tw-border tw-border-solid tw-border-[#854ec9] tw-cursor-pointer tw-transition-colors"
          >
            {showAll
              ? "Show fewer departures"
              : `Show ${hiddenCount} more departure${hiddenCount > 1 ? "s" : ""}`}
            <svg
              xmlns="http://www.w3.org/2000/svg"
              width="14"
              height="14"
              fill="currentColor"
              viewBox="0 0 16 16"
              className={`tw-transition-transform tw-duration-200 ${
                showAll ? "tw-rotate-180" : ""
              }`}
            >
              <path
                fillRule="evenodd"
                d="M1.646 4.646a.5.5 0 0 1 .708 0L8 10.293l5.646-5.647a.5.5 0 0 1 .708.708l-6 6a.5.5 0 0 1-.708 0l-6-6a.5.5 0 0 1 0-.708"
              />
            </svg>
          </button>
        </div>
      )}
    </div>
  );
}
