export default function getComission({ regularPrice, privatePrice }: {
    regularPrice: any;
    privatePrice: any;
}) {
    var regularPriceCreditPoint = 0;
    var privatePriceCreditPoint = 0;
    var totalCreditPoint = 0;
    // Ana site yalnız müşteri: kredi puanı oranı sabit %1 (operatör %2 dalı kalktı).
    var comissionRate = 1;

    if (regularPrice > 0)
        regularPriceCreditPoint = (regularPrice * comissionRate) / 100;

    if (privatePrice > 0)
        privatePriceCreditPoint = (privatePrice * comissionRate) / 100;

    if (regularPriceCreditPoint > privatePriceCreditPoint)
        totalCreditPoint = regularPriceCreditPoint;
    else
        totalCreditPoint = privatePriceCreditPoint;

    return {
        regularPriceCreditPoint,
        privatePriceCreditPoint,
        totalCreditPoint
    }
}