import { useEffect, useState, useRef } from "react";
import getTourPricing from "@/services/tourPricingService";
import { getCookie } from "cookies-next";
import TourCarousel from "../tour/tour-carousel";
import getData from "@/services/filterPageService";

export default function SimilarTours({
  destination,
  category,
}: {
  destination: any;
  category: any;
}) {
  const [loading, setLoading] = useState(true);
  const [data, setData] = useState([]);
  const isInitialMount = useRef(true);
  const [priceLoading, setPriceLoading] = useState(true);
  const [prices, setPrices] = useState<any[]>([
    {
      tourId: 0,
      price: 0,
      oldPrice: 0,
      paxLeft: 0,
      currency: "",
    },
  ]);

  const fetchData = async () => {
    setLoading(true);
    getData({
      page: 1,
      filterData: { destination, category },
      currency: "EUR",
    }).then((res) => {
      setData(res.tours);
      setPrices(
        res.tours.map((item: any) => {
          return {
            tourId: item.id,
            price: 0,
            oldPrice: 0,
            paxLeft: 0,
            currency: "",
          };
        })
      );
      setLoading(false);
    })
      // Ağ hatası / kullanıcı sayfadan ayrıldı / getData throw etti: sessizce yut.
      // Aksi halde unhandled rejection → "Failed to fetch" Sentry'e gürültü olur.
      .catch(() => setLoading(false));
  };

  useEffect(() => {
    fetchData();
  }, []);

  useEffect(() => {
    if (isInitialMount.current) {
      isInitialMount.current = false;
    } else {
      setPriceLoading(true);
      getTourPricing(
        prices.map((tour: any) => tour.tourId),
        getCookie("currency")
      ).then((res) => {
        setPrices(
          res.map((item: any) => {
            return {
              tourId: item.id,
              price: item.price,
              oldPrice: item.old_price,
              paxLeft: item.promotionDetail.pax_left ?? 0,
              currency: item.currency,
            };
          })
        );
        setPriceLoading(false);
      });
    }
  }, [data]);

  const skeleton = (
    <div className="tw-h-full tw-overflow-hidden tw-rounded-xl tw-border tw-border-solid tw-border-[#ebe7f0] tw-bg-white tw-animate-pulse">
      <div className="tw-w-full tw-h-[150px] tw-bg-gray-200"></div>
      <div className="tw-p-4">
        <div className="tw-h-4 tw-w-full tw-bg-gray-200 tw-rounded tw-mb-2"></div>
        <div className="tw-h-4 tw-w-1/2 tw-bg-gray-200 tw-rounded"></div>
      </div>
      <div className="tw-px-4 tw-pb-4">
        <div className="tw-h-4 tw-w-2/3 tw-bg-gray-200 tw-rounded"></div>
      </div>
    </div>
  );

  if (!loading && data.length === 0) return null;

  return (
    <div className="tw-mt-12 tw-pt-10 tw-border-0 tw-border-t tw-border-solid tw-border-[#ece9f1]">
      <h2 className="tw-font-display tw-text-[22px] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-mb-1">
        You might also like these tours
      </h2>
      <p className="tw-mt-0 tw-mb-6 tw-text-[14px] tw-text-[#5d556c]">
        Handpicked trips with a similar vibe — perfect if this one caught your eye.
      </p>
      {loading && (
        <div className="tw-grid tw-grid-cols-2 md:tw-grid-cols-3 lg:tw-grid-cols-4 tw-gap-4">
          {[...Array(4)].map((x, i) => (
            <div key={i}>{skeleton}</div>
          ))}
        </div>
      )}

      {!loading && (
        <TourCarousel
          tours={data}
          prices={prices}
          priceLoading={priceLoading}
        />
      )}
    </div>
  );
}
