export default function getPrice({ accommodation, prices, travelers }: { accommodation: boolean; prices: any; travelers: any; }) {
    var price = 0;
    var oldPrice = 0;
    var subTitle = "";
    travelers = parseInt(travelers);

    if (accommodation) {
        if (travelers >= 3) {
            if (prices.trp !== 0) {
                price = prices.trp;
                oldPrice = prices.old_trp;
                subTitle = "* Per person in Triple room.";
            }
            else if (prices.dbl !== 0) {
                price = prices.dbl;
                oldPrice = prices.old_dbl;
                subTitle = "* Per person in Double room.";
            }
            else if (prices.sng !== 0) {
                price = prices.sng;
                oldPrice = prices.old_sng;
                subTitle = "* Per person in Single room.";
            }
        }
        else if (travelers === 2) {
            if (prices.dbl !== 0) {
                price = prices.dbl;
                oldPrice = prices.old_dbl;
                subTitle = "* Per person in Double room.";
            }
            else if (prices.sng !== 0) {
                price = prices.sng;
                oldPrice = prices.old_sng;
                subTitle = "* Per person in Single room.";
            }
        }
        else {
            price = prices.sng;
            oldPrice = prices.old_sng;
            subTitle = "* Per person in Single room.";
        }
    } else {
        price = prices.adl;
        oldPrice = prices.old_adl;
        subTitle = "* Per person";
    }

    return { price, oldPrice, subTitle };
};