import React from "react";

const StarRating = ({ rating }: { rating: number }) => {
    const clampedRating = Math.max(0, Math.min(5, rating));
    return (
        <span className="tw-inline-flex tw-items-center" style={{ gap: "2px" }}>
            {Array.from({ length: 5 }, (_, i) => {
                const fillPercent = Math.max(0, Math.min(100, (clampedRating - i) * 100));
                return (
                    <div key={i} style={{ position: "relative", width: "14px", height: "14px" }}>
                        <svg
                            viewBox="0 0 24 24"
                            fill="#d1d5db"
                            style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%" }}
                        >
                            <path d="M12 17.27L18.18 21l-1.64-7.03L22 9.24l-7.19-.61L12 2 9.19 8.63 2 9.24l5.46 4.73L5.82 21z" />
                        </svg>
                        <div
                            style={{
                                position: "absolute",
                                top: 0,
                                left: 0,
                                height: "100%",
                                width: `${fillPercent}%`,
                                overflow: "hidden",
                            }}
                        >
                            <svg
                                viewBox="0 0 24 24"
                                fill="#f59e0b"
                                style={{ position: "absolute", top: 0, left: 0, width: "14px", height: "14px" }}
                            >
                                <path d="M12 17.27L18.18 21l-1.64-7.03L22 9.24l-7.19-.61L12 2 9.19 8.63 2 9.24l5.46 4.73L5.82 21z" />
                            </svg>
                        </div>
                    </div>
                );
            })}
        </span>
    );
};

export default StarRating;
