"use client";
import * as Sentry from "@sentry/nextjs";
import React, { useState } from "react";
import Lightbox from "yet-another-react-lightbox";
import Slideshow from "yet-another-react-lightbox/plugins/slideshow";
import Thumbnails from "yet-another-react-lightbox/plugins/thumbnails";
import Zoom from "yet-another-react-lightbox/plugins/zoom";
import Counter from "yet-another-react-lightbox/plugins/counter";
import "yet-another-react-lightbox/plugins/thumbnails.css";
import "yet-another-react-lightbox/plugins/counter.css";
import "yet-another-react-lightbox/styles.css";
import StarRating from "./star-rating";
import { apiClient } from "@/lib/apiClient";
import Modal from "./modal";
import { outlineBtnCls } from "./ui";
import { parsePlainDate } from "@/helpers/plainDate";

type MediaConversion = {
  thumb?: string;
  high?: string;
};

type Media = {
  id: number;
  name: string;
  file_name: string;
  mime_type: string;
  size: number;
  url: string;
  conversions?: MediaConversion;
};

type Review = {
  id: string;
  customer_display_name: string;
  title?: string | null;
  content: string;
  rating: string | number;
  review_source?: string | null;
  review_source_link?: string | null;
  review_date?: string | null;
  photos?: string[] | null;
  media?: Media[] | null;
};



const SourceBadge = ({
  source,
  link,
}: {
  source: string;
  link?: string | null;
}) => {
  const normalized = source.toLowerCase();

  const content = (
    <span
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: "5px",
        fontSize: "12px",
        color: "#4b5563",
        backgroundColor: "#f9fafb",
        border: "1px solid #e5e7eb",
        borderRadius: "6px",
        padding: "4px 10px",
        fontWeight: 500,
      }}
    >
      {normalized === "google" && (
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none">
          <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" fill="#4285F4" />
          <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853" />
          <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l3.66-2.84z" fill="#FBBC05" />
          <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335" />
        </svg>
      )}
      {normalized === "tripadvisor" && (
        <svg
          width="14"
          height="14"
          viewBox="0 0 512 512"
          xmlns="http://www.w3.org/2000/svg"
          fillRule="evenodd"
          clipRule="evenodd"
          strokeLinejoin="round"
          strokeMiterlimit="2"
        >
          <path
            d="M175.335 281.334c0 24.483-19.853 44.336-44.336 44.336-24.484 0-44.337-19.853-44.337-44.336 0-24.484 19.853-44.337 44.337-44.337 24.483 0 44.336 19.853 44.336 44.337zm205.554-44.337c-24.48 0-44.336 19.853-44.336 44.337 0 24.483 19.855 44.336 44.336 44.336 24.481 0 44.334-19.853 44.334-44.336-.006-24.47-19.839-44.31-44.309-44.323l-.025-.01v-.004zm125.002 44.337c0 68.997-55.985 124.933-124.999 124.933a124.466 124.466 0 01-84.883-33.252l-40.006 43.527-40.025-43.576a124.45 124.45 0 01-84.908 33.3c-68.968 0-124.933-55.937-124.933-124.932A124.586 124.586 0 0146.889 189L6 144.517h90.839c96.116-65.411 222.447-65.411 318.557 0H506l-40.878 44.484a124.574 124.574 0 0140.769 92.333zm-290.31 0c0-46.695-37.858-84.55-84.55-84.55-46.691 0-84.55 37.858-84.55 84.55 0 46.691 37.859 84.55 84.55 84.55 46.692 0 84.545-37.845 84.55-84.54v-.013.003zM349.818 155.1a244.01 244.01 0 00-187.666 0C215.532 175.533 256 223.254 256 278.893c0-55.634 40.463-103.362 93.826-123.786l-.005-.006h-.003zm115.64 126.224c0-46.694-37.858-84.55-84.55-84.55-46.691 0-84.552 37.859-84.552 84.55 0 46.692 37.855 84.55 84.553 84.55 46.697 0 84.55-37.858 84.55-84.55z"
            fill="#00af87"
            fillRule="nonzero"
          />
        </svg>
      )}
      <span style={{ marginLeft: "4px" }}>
        {normalized === "google"
          ? "Google"
          : normalized === "tripadvisor"
            ? "TripAdvisor"
            : source}
      </span>
    </span>
  );

  if (link) {
    return (
      <a
        href={link}
        target="_blank"
        rel="noopener noreferrer"
        style={{ textDecoration: "none" }}
      >
        {content}
      </a>
    );
  }

  return content;
};

const SingleReview = ({
  review,
  options,
  onImageClick
}: {
  review: Review;
  options: any;
  onImageClick?: (images: { src: string }[], startIndex: number) => void;
}) => {
  const allMedia = [
    ...(review.photos || []).map(p => ({ thumb: p, high: p })),
    ...(review.media || []).map(m => ({
      thumb: m.conversions?.thumb || m.url,
      high: m.conversions?.high || m.url
    }))
  ];

  const [isExpanded, setIsExpanded] = useState(false);
  const maxLength = 160;
  const contentStr = review.content || "";
  const showReadMore = contentStr.length > maxLength;
  const displayContent = (showReadMore && !isExpanded)
    ? contentStr.substring(0, maxLength) + "..."
    : contentStr;

  if (!review.customer_display_name?.trim() || review.rating === null || review.rating === undefined) {
    return null;
  }

  return (
    <div className="tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-p-5">
      <div className="tw-flex tw-items-start tw-gap-3">
        <img
          src="/images/no-profile.png"
          alt={review.customer_display_name}
          className="tw-rounded-full tw-shrink-0"
          style={{ width: "44px", height: "44px", objectFit: "cover", border: "1px solid #f3f4f6" }}
        />
        <div className="tw-grow tw-min-w-0">
          <div className="tw-flex tw-items-start tw-justify-between tw-gap-2">
            <div className="tw-min-w-0">
              <div className="tw-truncate tw-text-[15px] tw-font-semibold tw-text-[#14101c]">
                {review.customer_display_name}
              </div>
              <div className="tw-flex tw-items-center tw-flex-wrap tw-gap-2 tw-mt-1">
                <StarRating rating={Number(review.rating)} />
                {review.review_date && (
                  <span className="tw-text-[#5d556c]" style={{ fontSize: "13px" }}>
                    {new Intl.DateTimeFormat("en-US", options).format(
                      parsePlainDate(review.review_date)
                    )}
                  </span>
                )}
              </div>
            </div>
            {review.review_source && (
              <SourceBadge
                source={review.review_source}
                link={review.review_source_link}
              />
            )}
          </div>
        </div>
      </div>

      {review.title && (
        <div className="tw-mt-4 tw-font-bold tw-text-[#14101c]">
          {review.title}
        </div>
      )}

      <p className="tw-mt-2 tw-mb-0 tw-text-[#2a2336]" style={{ lineHeight: "1.6" }}>
        {displayContent}
        {showReadMore && !isExpanded && (
          <button
            onClick={() => setIsExpanded(true)}
            className="tw-bg-transparent tw-border-0 tw-p-0 tw-ml-1 tw-no-underline tw-font-semibold tw-text-[#854ec9] tw-cursor-pointer"
            style={{ fontSize: "14px", verticalAlign: "baseline" }}
          >
            Read More
          </button>
        )}
      </p>

      {allMedia.length > 0 && (
        <div className="tw-flex tw-flex-wrap tw-gap-2 tw-mt-3">
          {allMedia.map((m, i) => (
            <img
              key={`media-${i}`}
              src={m.thumb}
              alt={`Review media ${i + 1}`}
              onClick={() => {
                if (onImageClick) {
                  onImageClick(allMedia.map(item => ({ src: item.high })), i);
                }
              }}
              className="tw-rounded-lg tw-border tw-border-solid tw-border-[#ebe7f0]"
              style={{
                width: "80px",
                height: "80px",
                objectFit: "cover",
                cursor: "pointer",
              }}
            />
          ))}
        </div>
      )}
    </div>
  );
};

const Reviews = ({ tourData }: any) => {
  const [lightBoxIndex, setLightBoxIndex] = useState(-1);
  const [lightBoxImages, setLightBoxImages] = useState<{ src: string }[]>([]);

  const [modalReviews, setModalReviews] = useState<Review[]>([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [isLoading, setIsLoading] = useState(false);
  const [hasFetched, setHasFetched] = useState(false);
  const [showAll, setShowAll] = useState(false);

  const handleImageClick = (images: { src: string }[], index: number) => {
    setLightBoxImages(images);
    setLightBoxIndex(index);
  };

  const loadReviews = async (page: number) => {
    if (!tourData?.id) return;
    setIsLoading(true);
    try {
      // apiv3 B2C: GET /b2c/tours/{id}/tour-reviews (yeni tour_reviews sistemi).
      const result: any = await apiClient(
        `/b2c/tours/${tourData.id}/tour-reviews?page=${page}`
      );
      if (result && result.data) {
        setModalReviews((prev) => page === 1 ? result.data : [...prev, ...result.data]);
        if (result.meta && result.meta.last_page) {
          setTotalPages(result.meta.last_page);
        }
        setCurrentPage(page);
      }
    } catch (e) {
      Sentry.captureException(e);
    } finally {
      setIsLoading(false);
    }
  };

  const handleShowAll = () => {
    if (!hasFetched && tourData?.id) {
      loadReviews(1);
      setHasFetched(true);
    }
  };

  const allReviews: Review[] = (tourData?.reviews && tourData.reviews.length > 0)
    ? tourData.reviews
    : [];

  const firstFive = allReviews.slice(0, 5);

  if (allReviews.length === 0) return null;

  const options: Intl.DateTimeFormatOptions = {
    month: "short",
    day: "2-digit",
    year: "numeric",
  };

  return (
    <div className="tw-my-6" id="reviews">
      <h2 className="tw-font-display tw-text-[22px] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-pb-1">
        Reviews
      </h2>
      <div className="tw-mt-4 tw-mb-6 tw-flex tw-items-center tw-gap-4">
        <div className="tw-text-[42px] tw-font-bold tw-leading-none tw-text-[#14101c]">
          {(tourData?.rating || 4.8).toFixed(1)}
        </div>
        <div>
          <StarRating rating={tourData?.rating || 4.8} />
          <div className="tw-mt-1 tw-text-[14px] tw-text-[#5d556c]">
            Based on{" "}
            <span className="tw-font-semibold tw-text-[#14101c]">
              {tourData?.review_count || allReviews.length}
            </span>{" "}
            reviews
          </div>
        </div>
      </div>

      <div className="tw-flex tw-flex-col tw-gap-4">
        {firstFive.map((review) => (
          <SingleReview key={review.id} review={review} options={options} onImageClick={handleImageClick} />
        ))}
      </div>

      {allReviews.length > 5 && (
        <div className="tw-mt-6 tw-text-center">
          <button
            className={outlineBtnCls}
            onClick={() => {
              handleShowAll();
              setShowAll(true);
            }}
          >
            Show all {tourData?.review_count || allReviews.length} reviews
          </button>
        </div>
      )}

      {/* Modal for All Reviews */}
      <Modal
        open={showAll}
        onClose={() => setShowAll(false)}
        title="Customer Reviews"
        size="lg"
      >
        <div className="tw-flex tw-items-center tw-gap-2 tw-mb-6 tw-mt-2" style={{ fontSize: "14px" }}>
          <div className="tw-flex tw-items-center tw-gap-1">
            <span className="tw-font-bold tw-text-[#14101c]">{(tourData?.rating || 4.8).toFixed(1)}</span>
            <StarRating rating={tourData?.rating || 4.8} />
          </div>
          <span className="tw-text-[#5d556c]">·</span>
          <span className="tw-font-semibold tw-text-[#5d556c]">
            {tourData?.review_count || allReviews.length} reviews
          </span>
        </div>
        <div className="tw-flex tw-flex-col tw-gap-4">
          {modalReviews.length > 0 ? (
            modalReviews.map((review) => (
              <SingleReview key={`modal-${review.id}`} review={review} options={options} onImageClick={handleImageClick} />
            ))
          ) : isLoading ? (
            <div className="tw-text-center tw-my-6">Loading reviews...</div>
          ) : (
            allReviews.map((review) => (
              <SingleReview key={`modal-fallback-${review.id}`} review={review} options={options} onImageClick={handleImageClick} />
            ))
          )}
        </div>

        {hasFetched && currentPage < totalPages && (
          <div className="tw-text-center tw-mt-6 tw-mb-3">
            <button
              className={outlineBtnCls}
              onClick={() => loadReviews(currentPage + 1)}
              disabled={isLoading}
            >
              {isLoading ? "Loading..." : "Load More"}
            </button>
          </div>
        )}
      </Modal>

      <Lightbox
        slides={lightBoxImages}
        controller={{ closeOnBackdropClick: true }}
        index={lightBoxIndex}
        open={lightBoxIndex >= 0}
        close={() => setLightBoxIndex(-1)}
        counter={{ container: { style: { top: 0 } } }}
        plugins={[Slideshow, Thumbnails, Zoom, Counter]}
      />
    </div>
  );
};

export default Reviews;
