
export default function getPrice({ isRegular, regularPrice, oldRegularPrice, isPrivate, privatePrice, oldPrivatePrice, rooms }: {
    isRegular: boolean;
    regularPrice: number;
    oldRegularPrice: number;
    isPrivate: boolean;
    privatePrice: number;
    oldPrivatePrice: number;
    rooms: any;
}) {
    var priceType = "";
    var priceTypeDetail = "";
    var price = 0;
    var oldPrice = 0;
    var privateOption = false;
    var priceDesc = "per person";

    if (isRegular && regularPrice > 0) {
        priceType = "regular";
        priceTypeDetail = "Group Tour";
        price = regularPrice;
        oldPrice = oldRegularPrice;
    }
    else if (isPrivate && privatePrice > 0) {
        priceType = "private";
        priceTypeDetail = "Private Tour";
        price = privatePrice;
        oldPrice = oldPrivatePrice;
    }

    // if (rooms?.length > 0) {
    //     if (rooms.find((r: any) => r.id === "trp"))
    //         priceDesc = "pp in triple room"
    //     else if (rooms.find((r: any) => r.id === "dbl"))
    //         priceDesc = "pp in double room"
    //     else
    //         priceDesc = "pp in single room"
    // }

    return {
        priceType,
        priceTypeDetail,
        price,
        oldPrice,
        privateOption,
        priceDesc
    }
}