"use client";
import priceFormat from "@/helpers/priceFormat";
import { getCookie } from "cookies-next";
import getPrice from "@/helpers/getLastPrice";
import { useTourModals } from "./tour-modals-context";

export default function MobileFooterSticky({
  prices,
  departureType,
  availabilityLoading,
}: {
  prices: any;
  departureType: string;
  availabilityLoading: any;
}) {
  const { openInquiry } = useTourModals();

  const priceDetail = getPrice({
    isRegular: prices.is_regular,
    regularPrice: prices.regular_price,
    oldRegularPrice: prices.old_regular_price,
    isPrivate: prices.is_private,
    privatePrice: prices.private_price,
    oldPrivatePrice: prices.old_private_price,
    rooms: prices.rooms,
  });

  const smallPrimary =
    "tw-inline-flex tw-items-center tw-justify-center tw-w-full tw-px-3 tw-py-2 tw-rounded-full tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-text-[13px] tw-font-semibold tw-no-underline tw-border-0 tw-cursor-pointer tw-transition-colors tw-mb-1";
  const smallDark =
    "tw-inline-flex tw-items-center tw-justify-center tw-w-full tw-px-3 tw-py-2 tw-rounded-full tw-bg-[#14101c] hover:tw-bg-[#2a2336] tw-text-white tw-text-[13px] tw-font-semibold tw-border-0 tw-cursor-pointer tw-transition-colors";

  return (
    <div
      className="tw-fixed tw-bottom-0 tw-left-0 tw-right-0 tw-z-[1030] tw-bg-white tw-p-1 lg:tw-hidden"
      style={{ boxShadow: "0 0 12px rgba(133, 78, 201, .2)" }}
    >
      <div className="tw-flex tw-items-center">
        {availabilityLoading ? (
          <>
            <div className="tw-w-7/12 tw-pr-0 tw-animate-pulse">
              <div className="tw-mb-2 tw-h-4 tw-w-3/4 tw-rounded tw-bg-gray-200"></div>
              <div className="tw-h-4 tw-w-3/4 tw-rounded tw-bg-gray-200"></div>
            </div>
            <div className="tw-w-5/12 tw-animate-pulse">
              <div className={smallPrimary}>Check Availability</div>
              <div className={smallDark}>
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  width="18"
                  height="18"
                  fill="currentColor"
                  className="tw-mr-1"
                  viewBox="0 0 16 16"
                >
                  <path d="M8 15A7 7 0 1 1 8 1a7 7 0 0 1 0 14m0 1A8 8 0 1 0 8 0a8 8 0 0 0 0 16" />
                  <path d="M5.255 5.786a.237.237 0 0 0 .241.247h.825c.138 0 .248-.113.266-.25.09-.656.54-1.134 1.342-1.134.686 0 1.314.343 1.314 1.168 0 .635-.374.927-.965 1.371-.673.489-1.206 1.06-1.168 1.987l.003.217a.25.25 0 0 0 .25.246h.811a.25.25 0 0 0 .25-.25v-.105c0-.718.273-.927 1.01-1.486.609-.463 1.244-.977 1.244-2.056 0-1.511-1.276-2.241-2.673-2.241-1.267 0-2.655.59-2.75 2.286m1.557 5.763c0 .533.425.927 1.01.927.609 0 1.028-.394 1.028-.927 0-.552-.42-.94-1.029-.94-.584 0-1.009.388-1.009.94" />
                </svg>
                Ask a Question
              </div>
            </div>
          </>
        ) : (
          <>
          <div className="tw-w-7/12 tw-pr-0">
            {priceDetail.price > 0 && (
              <div className="tw-ml-2">
                <small className="tw-text-sm">
                  From{" "}
                  {priceDetail.oldPrice > 0 &&
                    priceDetail.price != priceDetail.oldPrice && (
                      <>
                        <span className="tw-line-through">
                          {priceFormat({
                            amount: priceDetail.oldPrice,
                            currency: getCookie("currency"),
                          })}
                        </span>{" "}
                        <span className="tw-inline-flex tw-items-center tw-rounded tw-bg-[#dc3545] tw-text-white tw-px-2 tw-py-0.5 tw-text-[11px] tw-font-semibold">
                          {"-" +
                            (
                              ((priceDetail.oldPrice - priceDetail.price) /
                                priceDetail.oldPrice) *
                              100
                            ).toFixed(0) +
                            "%"}
                        </span>
                      </>
                    )}
                </small>
                <br />
                <span>
                  <span className="tw-text-[18px] tw-font-bold tw-text-[#14101c]">
                    {priceFormat({
                      amount: priceDetail.price,
                      currency: getCookie("currency"),
                    })}{" "}
                  </span>
                  / <small className="tw-text-sm tw-text-[#5d556c]">{priceDetail.priceDesc}</small>
                </span>
                <div>
                  {priceDetail.oldPrice > 0 &&
                    priceDetail.price != priceDetail.oldPrice &&
                    (prices.availability?.promotionDetail?.pax_left ?? 0) > 0 && (
                      <span className="tw-font-bold tw-mr-2 tw-text-[#dc3545]">
                        <small className="tw-text-sm">
                          {(prices.availability?.promotionDetail?.pax_left ?? 0)} pax
                          left
                        </small>
                      </span>
                    )}
                </div>
              </div>
            )}
            {!prices.is_regular && !prices.is_private && (
              <p className="tw-font-bold tw-text-[#854ec9] tw-m-0 tw-text-center">
                Ask for the price and more.
              </p>
            )}
          </div>
          <div className="tw-w-5/12">
          {(prices.is_regular || prices.is_private) && (
            <a href="#availability" className={smallPrimary}>
              Check Availability
            </a>
          )}

          <button className={smallDark} type="button" onClick={openInquiry}>
            <svg
              xmlns="http://www.w3.org/2000/svg"
              width="18"
              height="18"
              fill="currentColor"
              className="tw-mr-1"
              viewBox="0 0 16 16"
            >
              <path d="M8 15A7 7 0 1 1 8 1a7 7 0 0 1 0 14m0 1A8 8 0 1 0 8 0a8 8 0 0 0 0 16" />
              <path d="M5.255 5.786a.237.237 0 0 0 .241.247h.825c.138 0 .248-.113.266-.25.09-.656.54-1.134 1.342-1.134.686 0 1.314.343 1.314 1.168 0 .635-.374.927-.965 1.371-.673.489-1.206 1.06-1.168 1.987l.003.217a.25.25 0 0 0 .25.246h.811a.25.25 0 0 0 .25-.25v-.105c0-.718.273-.927 1.01-1.486.609-.463 1.244-.977 1.244-2.056 0-1.511-1.276-2.241-2.673-2.241-1.267 0-2.655.59-2.75 2.286m1.557 5.763c0 .533.425.927 1.01.927.609 0 1.028-.394 1.028-.927 0-.552-.42-.94-1.029-.94-.584 0-1.009.388-1.009.94" />
            </svg>
            Ask a Question
          </button>
          </div>
          </>
        )}
      </div>
    </div>
  );
}
